#!/usr/bin/env python3
"""Duty Board v3.87.0 — Selling 2 at manual depth (pass 2 of 8).

Items & Price Lists restructured from 4 lessons to 9 full manual
chapters: the item master for selling field-by-field, units of measure
with the carton walkthrough, item-group tree design, price-list
architecture, the Item Price atom and the rate-0 clinic, bulk price
maintenance as an import workflow, multi-currency pricing, a complete
dual-channel pricing case study, and the support-patterns chapter.

Deploy: apply -> commit -> refresh JUST this module:
  bench --site xlevel.clouderp.one execute duty_board.academy_seed_sales_pro.refresh_lessons --kwargs "{'only': 'items_prices'}"

Anchored, idempotent. Requires v3.86.0.
Run from ~/frappe-bench/apps/duty_board.
"""

import io
import json
import os
import sys

INIT = "duty_board/__init__.py"
DATA_PATH = "duty_board/academy_sales_pro_data.json"
CHECK_ONLY = "--check" in sys.argv

L = lambda t, est, html: {"title": t, "est": est, "html": html}

LESSONS = [
L("Chapter 1 — The Item master for selling, field by field", "16", "<p>If the customer master answers <i>who</i>, the item master answers <i>what</i> — and just as in Selling 1, the quality of the master decides the quality of every document that touches it. This chapter walks the item record through a seller's eyes: which fields make an item sellable, findable, priceable, and reportable.</p><p><b>The gate: Is Sales Item.</b> One checkbox decides whether an item can appear on selling documents at all. Ticked, the item is offered on quotations, orders, delivery notes, invoices; unticked, it is invisible to the selling side no matter how much stock exists. This is deliberate: purchase-only components, internal consumables, packaging materials, and fixed assets live in the same item table but must never be quotable. The support reflex this creates — and it is the FIRST check, before price, before customer, before warehouse — is: <i>\"an item refuses to appear on a quotation\" → open the item → is Is Sales Item ticked?</i> Thirty seconds; ticket closed.</p><p><b>Item Code and Item Name.</b> The code is the permanent identity — short, unique, never recycled, never changed once transactions exist (a changed code orphans history). The name is the human label that prints on documents. Discipline for codes in Nigerian retail practice: a scheme the warehouse can read (PARA-500-TAB tells a picker more than ITM-0042), agreed once, enforced always. Duplicate items — the same product created twice under slightly different names — are the item-side twin of Selling 1's duplicate customers, and Chapter 9 treats the cure; here, build the habit: <b>search before you create</b>.</p><p><b>Item Group.</b> The reporting dimension. It serves for items <i>exactly</i> what Customer Group serves for customers: the segment/rollup axis every sales report slices by — Beverages, Antibiotics, Hardware, Services. It is a tree, designed (Chapter 3), not accreted. Note the symmetry consciously, because exam questions and client conversations both lean on it: customer group answers <i>what kind of buyer</i>; item group answers <i>what kind of product</i>; territory answers <i>where</i> — the three axes of every serious sales analysis.</p><p><b>Description.</b> What prints on documents beneath the name. Write it for the customer's eyes — spec, pack size, grade — because this text IS your quotation line. A blank description on a ₦5m line item reads as carelessness to the buyer's procurement office.</p><p><b>Maintain Stock.</b> Ticked for physical goods (the system tracks quantity); unticked for services and for bundle parents (Selling 8's Product Bundles). A consulting-fee item with Maintain Stock ticked will one day block an invoice for \"insufficient stock\" of something that never existed — a classic mis-setup found in the wild.</p><p><b>Flags that matter later.</b> <b>Has Serial No</b> and <b>Has Batch No</b> switch on per-unit and per-lot identity — their operational weight lands at delivery time (Selling 5: exact serials on the DN, recall-by-batch), but they are <i>set here</i>, at item creation, and retro-fitting them after transactions exist is painful. Pharma and electronics implementations decide these flags on day one.</p><p><b>Standard Selling Rate.</b> A convenience field used when no Item Price exists — a fallback, not the pricing system. Real rates live in Item Price records against price lists (Chapters 4-5); treat this field as scaffolding for brand-new setups, not as where pricing happens.</p>"),
L("Chapter 2 — Units of Measure: the carton walkthrough", "15", "<p>Nigerian trade sells in cartons, packs, dozens, bundles, jerrycans — and counts stock in pieces. The UOM machinery is how one item lives honestly in both worlds, and getting it wrong double-counts or twelfth-counts stock with real money attached. This chapter makes the arithmetic reflexive.</p><p><b>Default Unit of Measure — the counting unit.</b> The item's Default UOM is the unit stock is <i>kept and counted</i> in — the stock-keeping unit. If the warehouse counts pieces, Default UOM is Unit (Nos), full stop. Every stock report, every valuation, every bin quantity speaks this unit. It is not the carton size, not the price-list unit, not the selling unit — it is the physical count language of the warehouse, chosen once and never casually changed (a changed default UOM re-denominates history).</p><p><b>Sales UOM — the selling unit.</b> When you <i>sell</i> in a different unit than you count, set the Sales UOM. Stock in Units, sell in Cartons: Sales UOM = Carton. Selling documents then default to cartons for this item, which is how the trade actually talks.</p><p><b>The conversion factor — where the arithmetic lives.</b> In the item's UOM table, add the row: Carton, conversion factor <b>12</b> (one carton = twelve stock units). Now the system does the arithmetic everywhere, forever: a quotation for 5 Cartons prices 5 × the carton rate, and its delivery deducts <b>60 Units</b> from stock. One item record, two honest languages.</p><p><b>The wrong answers, and why they fail.</b> (1) <i>Two item records</i> — \"Paracetamol (Unit)\" and \"Paracetamol (Carton)\" — splits one physical stock into two ledgers that instantly disagree: sell a carton and the unit item's stock doesn't move; every stocktake becomes a reconciliation between two records of the same shelf. (2) <i>Manual arithmetic on rows</i> — \"just type 60 units when they order 5 cartons\" — survives until the first tired Friday, when 6 cartons ships as 6 units and a customer receives a twelfth of their order. The conversion factor exists so no human does trade arithmetic under deadline.</p><p><b>Multiple UOMs.</b> The table holds as many as trade needs: Unit (factor 1, the default), Pack of 4 (factor 4), Carton (factor 12), Pallet (factor 288). Documents can transact any of them; stock always resolves to the default UOM underneath.</p><p><b>Pricing meets UOM — a preview with teeth.</b> Item Prices (Chapter 5) are stated against a UOM. Price the Carton at ₦10,200 for carton-trade lists; the unit-retail list prices the Unit at ₦1,000. Keep list, UOM, and rate coherent — the classic field bug is a carton rate sitting on a unit row (an order of \"5\" priced as 5 cartons but understood by the warehouse as 5 units), and Chapter 9 shows how that ticket presents. The prevention is discipline you now have: <i>every rate knows its unit</i>.</p>"),
L("Chapter 3 — Item Groups: designing the product tree", "12", "<p>Selling 1 Chapter 2 taught segmentation-tree design for customers; this chapter is its mirror for products, shorter because the design logic transfers — and it should transfer consciously, since the symmetry itself is the lesson.</p><p><b>The mechanics.</b> Item Groups form a tree (group nodes and leaves); items attach to leaves; reports roll leaves up through parents. \"Analgesics\" and \"Antibiotics\" sum into \"Pharma\", which sums into the root. Sales Analytics grouped by Item Group is your product-mix instrument (Selling 6), and the tree you design here is the shape of every answer it will ever give.</p><p><b>The three rules, transferred.</b> (1) <b>One question per tree</b> — item group answers <i>what kind of product</i>. Do not encode supplier (that's the buying side), location (warehouses), or price tier (price lists) into group names. (2) <b>Mirror management's language</b> — if the MD asks \"how did Pharma do against FMCG?\", those are the top branches. (3) <b>Two-second leaves</b> — every item obviously belongs somewhere; if creation-time filing needs a debate, the tree is too clever. Ten to twenty leaves serves most mid-market catalogs.</p><p><b>A worked tree for a dual-channel distributor:</b> All Item Groups → <i>Pharma</i> (→ Analgesics · Antibiotics · Supplements), <i>FMCG</i> (→ Beverages · Personal Care · Home Care), <i>Equipment</i> (→ Retail Hardware · Spare Parts), <i>Services</i> (→ Installation · Support Plans). Note Services as a first-class branch: service items (Maintain Stock off, Chapter 1) deserve reporting identity too — firms that dump services into \"Misc\" cannot answer \"how much of our revenue is recurring service?\", which is exactly the question a SaaS-minded MD asks.</p><p><b>Groups as machinery.</b> As with customers, the group is a <i>condition</i> elsewhere: pricing rules target item groups (\"10% off all Beverages in Q4\", Selling 6), and sales-person targets are set per item group (Selling 8). A clean tree makes policy aimable; a mushy one makes every rule a special case.</p><p><b>Hygiene.</b> Same habits as Selling 1: a real default leaf in settings rather than a landfill, search-before-create, and a periodic review of recently created items. Re-parenting is cheap and takes effect in reports immediately; history filed into \"All Item Groups\" for a year is unsegmentable forever.</p><p><b>Two adjacent fields, placed correctly.</b> <b>Brand</b> is its own field on the item — Coca-Cola vs Rite Foods across the Beverages leaf — so brand analysis never needs brand-flavoured group names; keep brand out of the tree and in its field. And <b>item variants</b> (one template, many size/colour children) are the machinery for true variations of one product — a polo shirt in five sizes is one template with variants, not five leaves and not five unrelated items; if you find yourself designing group leaves per size, the variant system is what you actually wanted. Both belong to deeper item-master work, but knowing they exist stops the tree absorbing jobs that aren't its.</p>"),
L("Chapter 4 — Price Lists: the architecture of who pays what", "15", "<p>A <b>Price List</b> is a named collection of selling rates in <b>exactly one currency</b> — and that constraint is structural: the list IS a currency context, not a folder with a currency sticker. This chapter is about using lists as what they really are: the architecture of your commercial arrangements.</p><p><b>The defaulting chain — machinery you must recite cold.</b> Every selling document carries a price list field. The list lands there from the <b>customer's Default Price List</b> (Selling 1 Chapter 1); if the customer has none, the global default from Selling Settings applies. Each document row's rate is then looked up from <i>that document's list</i> in the Item Price table (Chapter 5). Customer → document → row: three links, and every pricing support ticket is a break in one of them.</p><p><b>Lists over discounts — the design principle with the reasons attached.</b> Retail pays ₦1,000; distributors pay ₦850. The clean model is <b>two lists — Standard Selling and Distributor NGN — each with its own Item Price</b>. The rejected alternatives, and why:</p><ul><li><i>A 15% distributor discount</i> — now every report shows ₦1,000 minus noise; margin analysis must mentally un-discount every row; \"discount\" as a word stops meaning anything exceptional; and the day you reprice retail, the distributor price moves too, whether you meant it or not. Coupled prices are accidental prices.</li><li><i>Two item records</i> — Chapter 2 already convicted this: one product, two stock ledgers.</li><li><i>Manual rate edits per document</i> — pricing by memory, enforced by nobody, invisible to every report.</li></ul><p>With separate lists, each channel's report shows its <b>true agreed rate</b>, each reprices independently, and discounts (Selling 6) are reserved for genuine exceptions — which keeps them visible, which keeps them controllable.</p><p><b>How many lists?</b> One per <i>commercial arrangement per currency</i>: Standard Selling (NGN retail), Distributor NGN, Key Accounts NGN (if negotiated tiers truly differ), Export USD. Four or five lists is architecture; fifteen is pricing chaos wearing a filing system — at that point the real structure you need is pricing rules over fewer lists.</p><p><b>Selling vs buying lists.</b> The same Price List doctype serves both sides, distinguished by its Selling / Buying checkboxes. A consultant never confuses which side a list feeds; the checkbox says. (Your purchase-cost story lives in the Buying track.)</p><p><b>Enabled/disabled.</b> Lists can be disabled — the right end for a retired arrangement, preserving history without offering the list on new documents. Deleting a list with history is the wrong end.</p>"),
L("Chapter 5 — Item Price records & the rate-0 clinic", "14", "<p>The price list is the folder; the <b>Item Price</b> is the atom: <b>one item + one price list + one rate</b>, optionally scoped. ₦1,000 for PARA-500 on Standard Selling is one record. Everything a document charges traces to one of these atoms — which is why the most common selling support ticket in existence resolves here.</p><p><b>The clinic: \"why is my rate 0?\"</b> A quotation row shows rate 0.00. The overwhelming cause: <b>no Item Price exists for that item on the document's price list</b>. The document asked its list; the list had no row for the item; zero came back — not an error, an honest empty answer. The diagnostic sequence, in order: (1) what price list is on the <i>document</i>? (2) does an Item Price exist for <i>this item on that list</i>? (3) if scoped — is today inside its validity window, and does the row's quantity meet its minimum? Ninety percent of tickets end at step 2 with a missing record; the rest at step 3 with an expired promo or an unmet min-qty. What the cause is NOT: the item being inactive (inactive items don't appear at all — Chapter 1), taxes (they compute after the rate), or the customer's territory (a reporting dimension, not a pricing input).</p><p><b>Scoping an Item Price.</b> Two optional fields turn a flat rate into a policy: <b>valid from / valid upto</b> dates — a September promo rate that starts and expires itself, no memo, no cleanup — and <b>minimum quantity</b> — ₦950 from 50 units up, coexisting with the standard ₦1,000 row; the document picks by quantity. These two, and only these two, are how an Item Price is scoped: not by warehouse, not by salesperson, not by payment terms (those concerns belong to other machinery entirely — pricing rules, sales-person assignment, terms templates).</p><p><b>UOM on the price.</b> From Chapter 2: every rate knows its unit. The carton rate is stated against the Carton UOM; the unit rate against Unit. A rate on the wrong UOM row is the silent 12× error, and Chapter 9 shows its ticket face.</p><p><b>Where rates come from — the recitation.</b> A document row's rate comes from <b>the Item Price for the document's price list</b> — not from the item's standard rate whenever a real Item Price exists (that field is fallback scaffolding, Chapter 1), not from the last invoice (there is no \"price memory\" between documents), not from Selling Settings. Say it until it's reflex, because half of pricing support is repeating this sentence with the screen open.</p><p><b>Coexisting rows, resolved.</b> When several Item Prices legitimately coexist for one item on one list — standard ₦1,000; promo ₦950 min-qty 50, dated — the document resolves by scope: quantity meets the minimum and today sits in the window → the scoped row wins; otherwise the standard row. And on the document itself notice the two fields per row: <b>Price List Rate</b> (what the lookup returned — the list's truth) and <b>Rate</b> (what this document charges). They start equal; a negotiated override changes Rate while Price List Rate stands as the reference — which is exactly how override reporting (Selling 3) can compare charged against list without archaeology.</p>"),
L("Chapter 6 — Bulk price maintenance: the import workflow", "12", "<p>Quarter-start. Costs moved, FX moved, and 300 selling rates must change by Monday. This chapter is the workflow that does it in an hour without a single typo becoming an invoice.</p><p><b>The principle: bulk price maintenance is an import job.</b> The cycle: <b>export → edit in the sheet → re-import</b>. Concretely: from the Item Price list, filter to the target price list, export via the data-export tool including the record IDs; open the sheet; update the rate column (this is where spreadsheet skill earns money — a formula applying +8% to a cost-driven subset beats 300 manual edits); re-import in <i>update</i> mode, matching on ID so each existing record is amended in place.</p><p><b>Why not the alternatives.</b> <i>Editing each Item Price by hand</i> — 300 open-edit-save cycles at human error rates; the one typo (₦10,200 entered as ₦1,020) ships on a real order before anyone notices. <i>Deleting the list and rebuilding</i> — history evaporates, scoped promo rows die with it, and for the rebuild window the list is empty: every document raised meanwhile prices at 0 (Chapter 5's clinic, self-inflicted, fleet-wide). <i>Patching with pricing rules</i> — a rule stacking +8% on stale base rates buries the true price under arithmetic; rules are for conditional policy (Selling 6), not for deferred maintenance of base rates.</p><p><b>The safety habits.</b> Export a backup copy of the list <i>before</i> editing (the rollback is then itself a one-import job). Spot-check ten rows after import against the sheet. Announce the effective date to the sales floor — quotations already in Draft keep their fetched rates until refreshed, and reps should know which world they're quoting in.</p><p><b>Validity-dated repricing — the elegant variant.</b> For a planned future change, import the <i>new</i> rates as additional Item Price rows with <b>valid from</b> = the effective date, and set <b>valid upto</b> on the old rows to the day before. The price change then executes itself at midnight, atomically, with zero downtime and a perfect audit trail of what was charged when — the professional's version of \"remember to update prices on the 1st\".</p><p><b>Cadence.</b> In an FX-exposed market, price review is a rhythm, not an event: a monthly thirty-minute review of cost-driven lists (with Chapter 7's currency machinery absorbing pure FX drift on export lists) keeps repricing boring — and boring is the goal.</p><p><b>Who owns repricing.</b> Give bulk price maintenance a named owner and a change log kept as the export files themselves — dated backup exports ARE the price history, reconstructible to any Monday. And pair the workflow with the Chapter 4 permission stance: with Allow-User-to-Edit-Price-List-Rate off for the sales floor (Selling 8), the import workflow is the ONLY door prices move through — one owner, one method, one trail. Firms that can answer \"who changed this rate, when, from what to what?\" in one minute are firms whose margins survive audits and arguments alike.</p>"),
L("Chapter 7 — Multi-currency pricing", "12", "<p>One list, one currency — so what happens when currencies meet? This chapter is the machinery and the architecture for pricing across the naira boundary.</p><p><b>The mechanics.</b> A <b>USD price list</b> is selected (or defaults) onto a document whose currency is <b>NGN</b>. The result is: not an error, not zero rates, not dollars printing on a naira invoice — ZhiftERP <b>converts automatically</b>, using the <b>Currency Exchange</b> rate, into the document's currency, and the document displays the conversion rate it used. The customer sees naira; the list stays dollars; the bridge is explicit and auditable on the document itself.</p><p><b>Where rates come from.</b> Currency Exchange records hold the rates, datestamped, and can auto-fetch daily from providers. For manual regimes (or CBN-vs-parallel realities), rates can be entered deliberately — and a document can carry an overridden conversion rate when a deal was struck at an agreed rate. The audit principle: <i>every converted amount traces to a visible rate on the document</i>.</p><p><b>The architecture win — import-priced goods.</b> Electronics, equipment, anything dollar-costed: hold the <b>stable dollar price on the USD list</b> and let conversion happen per document at the current rate. Your naira quotations then track FX automatically — no human reprices anything when the rate moves. The rejected alternative — maintaining a naira copy of dollar prices — goes stale the day the rate moves and turns every FX swing into Chapter 6's bulk-import job. One source of truth per price; conversion is computation, not maintenance.</p><p><b>The structuring rule, restated with currency.</b> One price list per <b>currency per commercial arrangement</b>: Distributor USD for the Ghana channel, Export USD for other West Africa, Standard Selling in NGN — and the <b>customer's default does the choosing</b> (Selling 1): the Accra distributor's master points at Distributor USD; the Surulere pharmacy at Standard Selling; nobody picks lists at quotation time and nobody quotes the wrong currency by accident.</p><p><b>The boundary of this module.</b> Multi-currency also touches the receivable's currency, exchange-gain/loss on settlement, and revaluation — accounting depths that belong to the Accounts track. A Sales <i>Professional</i> owns everything above: the pricing mechanics, the conversion trail on documents, and the architecture that keeps FX a computation instead of a monthly emergency.</p><p><b>Two field realities to handle gracefully.</b> First, <b>agreed-rate deals</b>: an export order struck at a locked ₦/$ rate carries that rate as the document's conversion override — deliberate, visible, and better than editing prices to fake it; the list stays pure, the deal stays honest. Second, <b>rounding</b>: converted amounts produce kobo-level fractions; currency precision settings and the invoice's rounding row absorb them so totals stay payable — never hand-round a converted rate on the row, because the payment allocation (Selling 7) must later match the document to the kobo.</p>"),
L("Chapter 8 — Case study: pricing architecture for a dual-channel vendor", "16", "<p>Everything in this module, executed once, end to end. The client is your own commercial reality in miniature; every step names its chapter.</p><p><b>The business.</b> HealthTrade Ltd sells pharmacy consumables two ways: retail counters buy by the <i>unit</i> at list; distributors buy by the <i>carton</i> (12s) at trade rates; and a Ghana distributor buys the same cartons priced in USD. A Q4 promo is planned: units at ₦950 from 50 units up, September–November. Build the whole pricing architecture.</p><p><b>Step 1 — The item, once (Ch. 1-2).</b> Item PARA-500, \"Paracetamol 500mg Tablets\", Is Sales Item ✓, Maintain Stock ✓, Item Group <i>Pharma → Analgesics</i> (Ch. 3's tree). Default UOM: <b>Unit</b> — the warehouse counts pieces. UOM table: add <b>Carton, factor 12</b>. One item record; both trade languages; the conversion factor owns the arithmetic forever. (Two item records was rejected in Chapter 2 and stays rejected.)</p><p><b>Step 2 — The lists (Ch. 4).</b> Three, one per arrangement per currency: <i>Standard Selling</i> (NGN — exists), <i>Distributor NGN</i>, <i>Distributor USD</i>. Not a \"distributor discount\" on the retail list — separate lists so each channel reports its true rate and reprices independently.</p><p><b>Step 3 — The Item Prices (Ch. 5).</b> Four atoms: PARA-500 · Standard Selling · <b>Unit</b> · ₦1,000. PARA-500 · Distributor NGN · <b>Carton</b> · ₦10,200. PARA-500 · Distributor USD · <b>Carton</b> · $6.80. And the promo: PARA-500 · Standard Selling · Unit · <b>₦950, min qty 50, valid 01-Sep → 30-Nov</b> — it will switch itself on, apply itself only to qualifying quantities, and expire itself, no memo ever written (Ch. 5-6). Note every rate declaring its UOM — the carton rate on the Carton row, the silent-12×-error made impossible.</p><p><b>Step 4 — Customers choose lists by default (Ch. 4; Selling 1).</b> Retail customers' masters: Standard Selling. Nigerian distributors: Distributor NGN. The Accra distributor: Distributor USD, currency USD on their master. From this moment, every quotation for every channel prices itself correctly with nobody choosing anything.</p><p><b>Step 5 — Verify end-to-end.</b> Draft quotations, one per channel (delete after): retail 60 units → ₦950 rate fires (min qty met, in window) ✓; retail 20 units → ₦1,000 ✓; distributor 5 Cartons → ₦10,200/carton, and the stock projection shows <b>60 Units</b> committed ✓ (Ch. 2's arithmetic, working); Accra 5 Cartons on an NGN document → converted at today's Currency Exchange rate, rate visible on the document ✓ (Ch. 7).</p><p><b>Step 6 — The maintenance plan (Ch. 6-7).</b> Distributor NGN reprices via export-edit-reimport when costs move, with validity-dated rows for planned changes; Distributor USD never chases FX — conversion does; the promo needs no cleanup — it dies on schedule. Handover note, four lines, filed in the client room.</p><p><b>What the architecture buys:</b> three channels, two currencies, one item, one stock ledger, self-managing promos, FX absorbed by computation — and every report showing true agreed rates per channel. Total build: under an hour. The firms that skip it spend that hour weekly, in support tickets, forever.</p>"),
L("Chapter 9 — Common mistakes & support patterns", "13", "<p>The scar tissue chapter for items and pricing: the tickets you will actually receive, the disease behind each, and the fix — plus the meta-pattern that by now you can predict.</p><p><b>Pattern 1 — \"Item doesn't appear on the quotation.\"</b> Disease: <b>Is Sales Item unticked</b> (Ch. 1). The first check, always. Runner-up disease: the item is disabled entirely. What it is not: pricing (an unpriced item appears at rate 0; a non-sales item doesn't appear at all — the symptom distinguishes the diseases).</p><p><b>Pattern 2 — \"Rate shows 0.\"</b> The clinic (Ch. 5): no Item Price for the item on <i>the document's</i> price list — or a scoped one whose window/min-qty doesn't match. Run the three-step diagnostic; fix the atom, not the document. Typing the rate onto the quotation \"just this once\" closes today's ticket and books tomorrow's — the next document asks the same empty list.</p><p><b>Pattern 3 — \"Customer was quoted 12× too much / warehouse shipped a twelfth of the order.\"</b> Disease: UOM incoherence (Ch. 2, 5) — a carton rate on a Unit row, or an order taken in the wrong UOM. Fix: correct the Item Price's UOM, verify the item's conversion table, re-issue the document. Prevention is the discipline: <i>every rate knows its unit</i>, checked at entry.</p><p><b>Pattern 4 — \"Distributor prices moved when we repriced retail.\"</b> Disease: channels coupled by a discount instead of separated by lists (Ch. 4). The %-off-retail \"distributor pricing\" faithfully tracked a retail change nobody meant to pass through. Fix: build the second list, migrate customers' defaults to it, retire the discount — decoupled channels reprice independently by construction.</p><p><b>Pattern 5 — \"Half the catalog priced at 0 since Tuesday.\"</b> Disease: a list rebuild done by delete-and-recreate, or an import that <i>created new</i> rows instead of <i>updating</i> existing ones, leaving the live list orphaned (Ch. 6). Fix: restore from the pre-edit export (you kept one — the workflow said so) and redo the import in update mode, matched on ID.</p><p><b>Pattern 6 — \"The Ghana invoice used a strange exchange rate.\"</b> Disease: a stale or manually mistyped Currency Exchange record, or a forgotten per-document override (Ch. 7). The document displays the rate it used — read it there first; the audit trail is on the page. Fix the exchange record or the override; re-issue if the deal rate was agreed differently.</p><p><b>Pattern 7 — \"Same product exists three times.\"</b> Disease: creation without search — PARA-500, \"Paracetamol 500\", \"Panadol tabs (white box)\" — each with partial stock and partial history (Ch. 1). Cure: pick the survivor, re-point and merge, retire the duplicates; then prevention — code discipline and search-before-create — because duplicates regrow wherever the habit that made them survives.</p><p><b>The meta-pattern, confirmed.</b> Seven tickets; seven master-data diseases wearing document symptoms — the same law Selling 1 closed on: <b>documents are downstream of masters</b>. On the selling side the masters are two: <i>who</i> (customer, Selling 1) and <i>what + at what rate</i> (item and Item Price, this module). Command both and the document layer — quotations onward, starting next module — becomes almost boring. That is the goal. Boring documents are correct documents.</p>"),
]


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if len(data.get("items_prices", {}).get("lessons", [])) == 9:
        print("Already applied. Nothing to do.")
        return
    if '"3.86.0"' not in init:
        sys.exit("ABORT: not at v3.86.0.")

    problems = []
    if len(LESSONS) != 9:
        problems.append(f"  {len(LESSONS)} lessons (want 9)")
    short = [l["title"] for l in LESSONS if len(l["html"]) < 2500]
    if short:
        problems.append(f"  below manual depth: {short}")
    if "ERPNext" in json.dumps(LESSONS):
        problems.append("  ERPNext branding leakage")
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    total = sum(len(l["html"]) for l in LESSONS)
    old_total = sum(len(l["html"]) for l in data["items_prices"]["lessons"])
    print(f"Selling 2: {len(data['items_prices']['lessons'])} lessons ({old_total:,} chars) -> 9 chapters ({total:,} chars, {total/old_total:.1f}x).")

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    data["items_prices"]["lessons"] = LESSONS
    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.86.0"', '"3.87.0"'))
    print("  data: Selling 2 -> 9 manual chapters")
